        return str(vars.get(name + '_response.data.ok')) == 'true'
    def num(x):
        try:
            return float(x)
        except Exception:
            return 0.0
    def tdate(s):
        s = str(s or '')
        if len(s) != 10:
            return ''
        return str(int(s[0:2])) + ' ' + MONTHS[int(s[3:5]) - 1] + ' ' + s[6:10]
    def iso(s):
        s = str(s or '')
        return s[6:10] + '-' + s[3:5] + '-' + s[0:2] if len(s) == 10 else ''
    def money(x, unit, sub):
        x = round(num(x), 2)
        whole = int(abs(x))
        cents = int(round((abs(x) - whole) * 100))
        text = '{:,}'.format(whole).replace(',', '.') + ' ' + unit
        if cents:
            text = text + ' ' + str(cents) + ' ' + sub
        return text
    def spell(d):
        return ' '.join(DIGIT_WORDS[int(c)] for c in str(d) if c.isdigit())
    def safe_name(n):
        n = str(n or '').strip()
        if not n or len(n.split()) > MAX_WORDS or len(n) > 40 or any(c in n for c in ':;<>[]()') or any(c.isdigit() for c in n):
            return ''
        return n
    def tr_lower(s):
        return str(s or '').replace('İ', 'i').replace('I', 'ı').lower().strip()
    def join_tr(items):
        return items[0] if len(items) == 1 else ', '.join(items[:-1]) + ' ve ' + items[-1]
    def cards():
        try:
            return json.loads(vars.get('cards_json') or '[]')
        except Exception:
            return []
    def eligible():
        return [c for c in cards() if c['main']]
    def say(line):
        vars['last_line'] = line
        vars['guide'] = 'Say exactly: "' + line + '"'
    def ask_again(line):
        n = int(num(vars.get('tries'))) + 1
        vars['tries'] = n
        if n >= MAX_TRIES:
            vars['route'] = 'close_tries'
        else:
            say(line)
    def names_line():
        names = []
        for c in eligible():
            nm = c['name'] or ('sonu ' + spell(c['last4']) + ' ile biten kart')
            if nm not in names:
                names.append(nm)
        return join_tr(names) if names else ''
