            vars['route'] = routes[kind]
            return True
        if kind == 'outside':
            vars['outside_pending'] = 'yes'
            vars['guide'] = 'Say exactly: "' + LINES['outside_ask'] + '"'
            return True
        if kind == 'menu_yes' and vars.get('outside_pending') == 'yes':
            vars['route'] = 'close_outside'
            return True
        if kind in ('stay', 'menu_yes'):
            vars['outside_pending'] = 'no'
            vars['guide'] = 'Say exactly: "' + str(vars.get('last_line') or '') + '"'
            return True
