            n = int(num(vars.get('calm_count'))) + 1
            vars['calm_count'] = n
            if n > CALM:
                vars['route'] = 'close_agent'
            else:
                vars['guide'] = 'Say exactly: "' + LINES['calm'] + ' ' + str(vars.get('last_line') or '') + '"'
            return True
        if kind == 'secret':
            vars['guide'] = 'Say exactly: "' + LINES['no_pin'] + ' ' + str(vars.get('last_line') or '') + '"'
            return True
        if kind == 'card_digits':
            vars['guide'] = 'Say exactly: "' + LINES['card_digits'] + ' ' + str(vars.get('last_line') or '') + '"'
            return True
        if kind == 'repeat':
            vars['guide'] = 'Say again exactly: "' + str(vars.get('last_line') or '') + '"'
            return True
        if kind == 'silence':
            n = int(num(vars.get('silence_count'))) + 1
            vars['silence_count'] = n
            if n >= 3:
                vars['route'] = 'close_silence'
            else:
                vars['guide'] = 'Say exactly: "' + str(vars.get('last_line') or '') + '"'
            return True
        return False

    def offer():
        if vars.get('has_email') == 'yes':
            return LINES['offer_both']
        return LINES['offer_week']

    vars['route'] = ''
    kind = str(params.get('kind') or 'unclear')
    week = ''.join(ch for ch in str(params.get('week') or '') if ch.isdigit())
    stage = str(vars.get('after_stage') or 'offer')
    if kind == 'yes' and vars.get('outside_pending') != 'yes':
        kind = dict(another='another_yes', email_offer='email').get(stage, 'unclear')
        if kind == 'unclear' and (stage == 'offer_week' or vars.get('has_email') != 'yes'):
            kind = 'week_change'
    if kind == 'no':
        kind = 'another_no' if stage == 'another' else 'done'
    def email():
        if vars.get('has_email') == 'yes':
            vars['tries'] = 0
            vars['last_line'] = vars.get('email_line')
            vars['route'] = 'email_confirm'
        elif vars.get('has_email') == 'error':
            vars['route'] = 'close_error'
        else:
            vars['after_stage'] = 'offer_week'
            say(LINES['no_email'] + ' ' + LINES['offer_week'])
    if common(kind):
        pass
    elif kind == 'another_yes':
        if len(eligible()) > 1:
            vars['pick_line'] = pick_line()
            vars['last_line'] = vars['pick_line']
            vars['tries'] = 0
            vars['route'] = 'choose_card'
        else:
            vars['after_stage'] = 'offer'
            say(offer())
    elif kind == 'another_no':
        vars['after_stage'] = 'offer'
        say(offer())
    elif kind == 'email':
        email()
    elif kind == 'email_old':
        if vars.get('has_email') == 'yes':
            vars['after_stage'] = 'email_offer'
            say(LINES['only_last'] + ' ' + str(vars.get('email_line')))
        else:
            email()
    elif kind == 'week_change':
        vars['week_wanted'] = week
        vars['tries'] = 0
        vars['route'] = 'week_get'
    elif kind == 'done':
        vars['route'] = 'close_menu'
    else:
        ask_again(str(vars.get('last_line') or offer()))

    if vars.get('route'):
        vars['guide'] = 'Say nothing now. The call goes on by itself.'
    pass
